using System.Text.Json;
using Microsoft.AspNetCore.Http;
using SonadaBeds.Web.Models;
namespace SonadaBeds.Web.Data;
public class CartService(IHttpContextAccessor accessor, SonadaDbContext db){const string Key="sonada-cart"; public List<CartItem> Items{get{var s=accessor.HttpContext?.Session.GetString(Key);return string.IsNullOrEmpty(s)?[]:JsonSerializer.Deserialize<List<CartItem>>(s)??[];}} public async Task AddAsync(int productId,int quantity,Dictionary<string,string>? options){var p=await db.Products.FindAsync(productId)??throw new KeyNotFoundException(); var items=Items; var price=p.BasePrice; if(options!=null)foreach(var value in options.Values){var o=p.Options.FirstOrDefault(x=>x.Name==value);if(o!=null)price+=o.PriceAdjustment;} var existing=items.FirstOrDefault(x=>x.ProductId==productId&&x.ConfigurationJson==JsonSerializer.Serialize(options??[]));if(existing!=null)existing.Quantity+=quantity;else items.Add(new CartItem{ProductId=p.Id,ProductName=p.Name,UnitPrice=price,Quantity=quantity,ConfigurationJson=JsonSerializer.Serialize(options??[]) });Save(items);} public void Remove(int id){var items=Items;items.RemoveAll(x=>x.Id==id||x.ProductId==id);Save(items);} public void Clear()=>Save([]); public decimal Subtotal=>Items.Sum(x=>x.UnitPrice*x.Quantity);void Save(List<CartItem> items)=>accessor.HttpContext?.Session.SetString(Key,JsonSerializer.Serialize(items));}
